cases.script:
put_le16() { local v=$1 i b; for ((i=0; i<2; i++)); do printf -v b '\\%03o' "$((v & 255))"; printf '%b' "$b"; v=$((v >> 8)); done; }
put_le32() { local v=$1 i b; for ((i=0; i<4; i++)); do printf -v b '\\%03o' "$((v & 255))"; printf '%b' "$b"; v=$((v >> 8)); done; }
zeros() { local n=$1; while ((n > 0)); do printf '\000'; n=$((n - 1)); done; }
emit() { local type=$1 pid=$2 sec=$3 usec=$4 line=$5 ident=$6 user=$7 host=$8; { put_le16 "$type"; zeros 2; put_le32 "$pid"; printf '%-32s%-4s%-32s%-256s' "$line" "$ident" "$user" "$host"; zeros 8; put_le32 "$sec"; put_le32 "$usec"; zeros 36; } >> records; }
: > records
emit 7 4242 1700000000 123000 pts/7 s7 alice fixture.example
emit 6 777 1700000000 0 tty8 ty ignored should-not-appear
utmp dump records

